window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[347]={"id":"347","numero":347,"titre":"Rétention aiguë d'urine","objectifs":[{"id":"347-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition de la rétention aiguë d’urine","contenu":"<p>La <span class=\"kw-def\">rétention aiguë d'urine</span> (RAU) se définit comme l'<span class=\"kw-def\">impossibilité totale et brutale d'uriner malgré la réplétion vésicale</span>, accompagnée d'une <span class=\"kw-clinique\">envie pressante et douloureuse d'uriner</span>.</p>\n      <table >\n        <thead><tr><th>Item</th><th>Caractéristique</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Mécanisme</strong></td><td>blocage <span class=\"kw-clinique\">total</span> et <span class=\"kw-clinique\">brutal</span> de la vidange, vessie pleine et sous tension</td></tr>\n          <tr><td><strong>Sex-ratio</strong></td><td>pathologie <span class=\"kw-clinique\">essentiellement masculine</span>, en dehors du contexte de vessie neurologique</td></tr>\n          <tr><td><strong>Symptômes</strong></td><td>patient <span class=\"kw-clinique\">algique</span>, <span class=\"kw-clinique\">anxieux</span>, <span class=\"kw-clinique\">agité</span>, avec une <span class=\"kw-clinique\">envie permanente d'uriner</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Globe vésical</strong> — signe physique majeur, diagnostic clinique facile : vessie <span class=\"kw-clinique\">douloureuse</span> et <span class=\"kw-clinique\">tendue</span>.</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Masse sus-pubienne</span> douloureuse (la palpation augmente l'envie d'uriner)</li>\n        <li>Voussure à <span class=\"kw-clinique\">convexité supérieure</span></li>\n        <li><span class=\"kw-clinique\">Mate à la percussion</span></li>\n      </ul>\n      <div class=\"obj-callout success\"><strong>Le mot-clé.</strong> RAU = blocage <span class=\"kw-clinique\">brutal</span> + <span class=\"kw-clinique\">douleur</span> + <span class=\"kw-clinique\">globe vésical</span> (vessie pleine). À distinguer formellement de l'<span class=\"kw-alerte\">anurie</span> (vessie vide) — voir objectif dédié.</div>","frequence":0},{"id":"347-2","rang":"B","rubrique":"Physiopathologie","titre":"Connaître la physiopathologie de la rétention aiguë d’urine","contenu":"<p>Une <span class=\"kw-def\">miction normale</span> nécessite l'intégrité coordonnée de trois éléments.</p>\n      <table >\n        <thead><tr><th>Élément</th><th>Rôle</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\"><strong>Réservoir</strong></span> (vessie)</td><td>doit se <span class=\"kw-clinique\">remplir facilement</span> (compliance) et se <span class=\"kw-clinique\">contracter efficacement</span> (détrusor)</td></tr>\n          <tr><td><span class=\"kw-def\"><strong>Filière urétrale</strong></span></td><td>col vésical, prostate, sphincter strié, urètre : assure la <span class=\"kw-clinique\">continence</span> (entre <span class=\"kw-clinique\">les</span> mictions) et le <span class=\"kw-clinique\">libre passage des urines</span> (durant la miction)</td></tr>\n          <tr><td><span class=\"kw-def\"><strong>Système nerveux</strong></span></td><td>contrôle <span class=\"kw-clinique\">les</span> phases de remplissage et per/post-mictionnelles ; assure la <span class=\"kw-clinique\">synergie vésico-sphinctérienne</span> (la vessie ne se contracte qu'<em>après</em> relâchement du sphincter)</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Trois mécanismes possibles de RAU</strong></p>\n      <table >\n        <thead><tr><th>Mécanisme</th><th>Fréquence</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\">Obstacle sous-vésical</span></td><td><strong>le plus souvent</strong></td></tr>\n          <tr><td><span class=\"kw-etio\">Altération de la commande neurologique</span></td><td>fréquent</td></tr>\n          <tr><td><span class=\"kw-etio\">Défaut de contraction vésicale</span> (détrusor)</td><td>plus rarement</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Logique.</strong> Tout ce qui <span class=\"kw-clinique\">obstrue</span> la filière, <span class=\"kw-clinique\">débranche</span> la commande nerveuse, ou <span class=\"kw-clinique\">épuise</span> le détrusor peut aboutir à une RAU. L'<span class=\"kw-etio\">obstacle sous-vésical</span> (HBP +++) domine chez l'homme.</div>","frequence":0},{"id":"347-3","rang":"A","rubrique":"Etiologie","titre":"Connaître les principales causes de rétention aiguë d’urine","contenu":"<p>On distingue <span class=\"kw-clinique\">les</span> causes <span class=\"kw-etio\">mécaniques</span> (obstacle), <span class=\"kw-etio\">fonctionnelles</span> (neurologiques) et <span class=\"kw-etio\">iatrogènes / médicamenteuses</span>.</p>\n      <h4 class=\"kw-def\">Causes mécaniques (obstacle sous-vésical)</h4>\n      <table >\n        <thead><tr><th>Cause</th><th>Points clés</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\"><strong>HBP</strong></span></td><td>cause n°1 chez l'homme. Risque de RAU majoré par l'<span class=\"kw-chiffre\">âge</span> et la sévérité des symptômes (<span class=\"kw-chiffre\">IPSS &gt; 7</span>). Ablation de sonde tentée après <span class=\"kw-chiffre\">48 h</span> d'<span class=\"kw-ttt\">α-bloquant</span> ; <span class=\"kw-ttt\">chirurgie</span> si échec de désondage ou HBP compliquée/sévère</td></tr>\n          <tr><td><span class=\"kw-etio\"><strong>Prostatite aiguë</strong></span></td><td>dérivation préférentielle par <span class=\"kw-clinique\">cathéter sus-pubien</span> ; <span class=\"kw-ttt\">C3G IV</span> ou <span class=\"kw-ttt\">fluoroquinolone</span> probabiliste puis adaptée <span class=\"kw-chiffre\">14–21 j</span> ; <span class=\"kw-ttt\">α-bloquant</span> possible</td></tr>\n          <tr><td><span class=\"kw-etio\"><strong>Sténose de l'urètre</strong></span></td><td>post-traumatique, post-infectieuse (<span class=\"kw-clinique\">urétrite</span>/IST), <span class=\"kw-etio\">iatrogène</span> (sondage traumatique, <span class=\"kw-ttt\">chirurgie</span> endoscopique). CAT : <span class=\"kw-clinique\">cathéter sus-pubien</span> (le sondage aggrave <span class=\"kw-clinique\">les</span> lésions) ; bilan par <span class=\"kw-imagerie\">UCRM</span></td></tr>\n          <tr><td><span class=\"kw-alerte\"><strong>Traumatisme de l'urètre</strong></span></td><td>polytraumatisme avec fracture du bassin + <span class=\"kw-clinique\">urétrorragie</span> ; <span class=\"kw-clinique\">cathéter sus-pubien d'emblée</span> (<span class=\"kw-ci\">sondage urétral contre-indiqué</span>) ; prise en charge différée, UCRM préalable</td></tr>\n          <tr><td><span class=\"kw-etio\"><strong>Caillotage vésical</strong></span></td><td>sonde double-courant de gros calibre (<span class=\"kw-chiffre\">22–24 Ch</span>) + lavage vésical continu ; décaillotage au lit ou au bloc ; bilan d'<span class=\"kw-clinique\">hématurie macroscopique</span></td></tr>\n          <tr><td><span class=\"kw-etio\"><strong>Autres</strong></span></td><td>cancer de prostate (RAU si localement avancé <span class=\"kw-chiffre\">T3–T4</span>) ; <span class=\"kw-etio\">calcul de vessie</span> ; <span class=\"kw-etio\">prolapsus génital</span> (réduire le prolapsus) ; <span class=\"kw-etio\">phimosis serré</span> (cathéter sus-pubien si sonde impossible + circoncision différée)</td></tr>\n        </tbody>\n      </table>\n      <h4 class=\"kw-def\">Causes fonctionnelles</h4>\n      <table >\n        <thead><tr><th>Origine</th><th>Étiologies</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\"><strong>Neurologiques</strong></span><br>(bilan urodynamique à distance)</td><td><strong>SNC :</strong> <span class=\"kw-etio\">SEP</span>, compression/<span class=\"kw-clinique\">lésion</span> médullaire, <span class=\"kw-etio\">Parkinson</span>, <span class=\"kw-etio\">AVC</span>, lésions congénitales de la moelle (spina-bifida)<br><strong>SNP :</strong> <span class=\"kw-etio\">diabète</span>, <span class=\"kw-ttt\">chirurgie</span> d'exentération pelvienne (rectum, utérus)</td></tr>\n          <tr><td><span class=\"kw-etio\"><strong>Autres fonctionnelles</strong></span></td><td><span class=\"kw-clinique\">cystite</span> aiguë, vulvo-vaginite herpétique (femme) ; fécalome, hémorroïdes (réflexes par pathologie anorectale)</td></tr>\n        </tbody>\n      </table>\n      <h4 class=\"kw-def\">Causes iatrogènes et médicamenteuses</h4>\n      <table >\n        <thead><tr><th>Classe</th><th>Molécules / contexte</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-ttt\"><strong>Anticholinergiques</strong></span><br>(risque ↑ si RPM &gt; <span class=\"kw-chiffre\">100 mL</span>)</td><td>collyres mydriatiques (<span class=\"kw-ttt\">atropine</span>, cyclopentolate, tropicamide) ; anticholinergiques vésicaux (oxybutynine, toltérodine, trospium) ; neuroleptiques phénothiaziniques ; antidépresseurs tricycliques ; certains antiparkinsoniens ; <span class=\"kw-ttt\">néfopam</span>, tiémonium ; antihistaminiques (hydroxyzine…)</td></tr>\n          <tr><td><span class=\"kw-ttt\"><strong>Morphiniques</strong></span></td><td>rachianesthésie / péridurale (le plus souvent) ; fortes doses orales, SC ou IV</td></tr>\n          <tr><td><span class=\"kw-ttt\"><strong>Autres</strong></span> (moins fréquents)</td><td><span class=\"kw-ttt\">inhibiteurs calciques</span> ; β-2-mimétiques (<span class=\"kw-ttt\">salbutamol</span>, terbutaline) ; sympathomimétiques (pseudo-éphédrine, phényléphrine, éphédrine)</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 125 — Trouble miction - incontinence urinaire · 161 — <span class=\"kw-clinique\">Infection urinaire</span> · 310 — Tumeur prostate · 104 — SEP · 265 — Lithiase urinaire</em></p>","frequence":0},{"id":"347-4","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les éléments cliniques de la rétention aiguë d’urine","contenu":"<p>Le diagnostic est <span class=\"kw-clinique\">clinique</span> : tableau douloureux brutal + <span class=\"kw-clinique\">globe vésical</span>. L'examen recherche en plus l'étiologie.</p>\n      <h4 class=\"kw-def\">Signes fonctionnels</h4>\n      <ul>\n        <li>Patient <span class=\"kw-clinique\">algique, anxieux, agité</span>, avec <span class=\"kw-clinique\">envie permanente et douloureuse d'uriner</span></li>\n        <li>Impossibilité <span class=\"kw-clinique\">totale et brutale</span> d'uriner</li>\n      </ul>\n      <h4 class=\"kw-def\">Globe vésical (signe physique majeur)</h4>\n      <ul>\n        <li><span class=\"kw-clinique\">Masse sus-pubienne</span> douloureuse, tendue (la palpation augmente l'envie d'uriner)</li>\n        <li>Voussure à <span class=\"kw-clinique\">convexité supérieure</span></li>\n        <li><span class=\"kw-clinique\">Matité</span> à la percussion</li>\n      </ul>\n      <h4 class=\"kw-def\">Examen physique orienté (étiologie)</h4>\n      <table >\n        <thead><tr><th>Examen</th><th>Recherche</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\"><strong>Toucher rectal</strong></span></td><td>prostate <span class=\"kw-clinique\">douloureuse</span> (<span class=\"kw-clinique\">prostatite</span> aiguë) ; <span class=\"kw-etio\">fécalome</span> ; pathologie de l'ampoule rectale (hémorroïdes, tumeur du rectum)</td></tr>\n          <tr><td><span class=\"kw-clinique\"><strong>Toucher vaginal</strong></span></td><td>tumeur gynécologique, <span class=\"kw-etio\">prolapsus génital</span> ; trophicité des tissus vaginaux</td></tr>\n          <tr><td><span class=\"kw-clinique\"><strong>Examen des OGE</strong></span></td><td><span class=\"kw-etio\">phimosis serré</span> (homme), <span class=\"kw-etio\">sténose du méat urétral</span> (homme et femme), <span class=\"kw-clinique\">orchi-épididymite</span> (± prostatite)</td></tr>\n        </tbody>\n      </table>\n      <h4 class=\"kw-def\">Interrogatoire — <span class=\"kw-def\">terrain</span></h4>\n      <ul>\n        <li><strong>Circonstances :</strong> spontanée ou favorisée (anesthésie générale/locorégionale) ; dysurie, brûlures mictionnelles ; <span class=\"kw-clinique\">hyperthermie</span>, frissons ; <span class=\"kw-clinique\">hématurie macroscopique</span></li>\n        <li><strong>ATCD urologiques :</strong> RAU, HBP, cancer prostate/vessie, <span class=\"kw-clinique\">prostatite</span>, infection urinaire, sténose urétrale, <span class=\"kw-ttt\">chirurgie</span> endoscopique, sondages</li>\n        <li><strong>ATCD neurologiques :</strong> <span class=\"kw-clinique\">lésion</span> médullaire, SEP, spina-bifida, Parkinson, <span class=\"kw-etio\">diabète</span>, <span class=\"kw-alerte\">AVC</span></li>\n        <li><strong>Traitements en cours :</strong> inducteurs de RAU, <span class=\"kw-ttt\">anti-thrombotiques</span> (gênent le <span class=\"kw-ttt\">drainage</span>)</li>\n      </ul>","frequence":0},{"id":"347-5","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les présentations cliniques atypiques de rétention aiguë d’urine","contenu":"<p>Dans certains terrains, la RAU est de diagnostic <span class=\"kw-alerte\">difficile</span> car la <span class=\"kw-clinique\">symptomatologie est fruste</span>, parfois <span class=\"kw-alerte\">indolore</span> — piège classique.</p>\n      <table >\n        <thead><tr><th><span class=\"kw-def\">Terrain</span></th><th>Présentation atypique</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\"><strong>Personne âgée</strong></span></td><td><span class=\"kw-clinique\">confusion</span>, désorientation temporo-spatiale, <span class=\"kw-clinique\">agitation</span>, anxiété, <span class=\"kw-clinique\">dyspnée</span> — la RAU se masque derrière un tableau gériatrique aspécifique</td></tr>\n          <tr><td><span class=\"kw-clinique\"><strong>Patient diabétique</strong></span></td><td><span class=\"kw-clinique\">hypoesthésie vésicale</span> → <span class=\"kw-alerte\">rétention indolore</span></td></tr>\n          <tr><td><span class=\"kw-clinique\"><strong>Blessé médullaire / sous anesthésie</strong></span></td><td>rétention urinaire <span class=\"kw-alerte\">indolore</span> (perte de la perception)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Réflexe.</strong> Devant toute <span class=\"kw-clinique\">confusion</span> ou <span class=\"kw-clinique\">agitation inexpliquée</span> du sujet âgé, et chez le <span class=\"kw-clinique\">diabétique</span> ou le <span class=\"kw-clinique\">blessé médullaire</span>, penser à <span class=\"kw-clinique\">palper le globe</span> / faire une <span class=\"kw-imagerie\">échographie vésicale</span> : la douleur peut manquer.</div>","frequence":0},{"id":"347-6","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les signes cliniques distinguant la rétention aiguë d’urine de l’anurie","contenu":"<p>Distinction <strong>fondamentale</strong> : la RAU est un obstacle à la <span class=\"kw-clinique\">vidange</span> (<span class=\"kw-clinique\">vessie pleine</span>), l'<span class=\"kw-alerte\">anurie</span> est un défaut de <span class=\"kw-bio\">filtration glomérulaire</span> (<span class=\"kw-clinique\">vessie vide</span>). Le <span class=\"kw-clinique\">globe</span> tranche.</p>\n      <table >\n        <thead><tr><th></th><th>Rétention aiguë d'urine</th><th>Anurie</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Mécanisme</strong></td><td>obstacle à l'<span class=\"kw-clinique\">évacuation</span> (vessie pleine)</td><td>absence de <span class=\"kw-bio\">filtration glomérulaire</span> (pas de production d'urine)</td></tr>\n          <tr><td><strong>Globe vésical</strong></td><td><span class=\"kw-clinique\">présent</span> (<span class=\"kw-clinique\">masse</span> sus-pubienne, mate, douloureuse)</td><td><span class=\"kw-clinique\">absent</span> (vessie vide)</td></tr>\n          <tr><td><strong>Diurèse</strong></td><td>urine présente en amont, bloquée</td><td><span class=\"kw-chiffre\">&lt; 200 mL/24 h</span></td></tr>\n          <tr><td><strong>Envie d'uriner</strong></td><td><span class=\"kw-clinique\">impérieuse et douloureuse</span></td><td>absente</td></tr>\n          <tr><td><strong>En cas de doute</strong></td><td colspan=\"2\"><span class=\"kw-imagerie\">échographie vésicale</span> : globe = RAU ; vessie vide = anurie</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong>Piège à ne pas inverser.</strong> Sonder une <span class=\"kw-alerte\">anurie</span> ne ramène <span class=\"kw-clinique\">pas d'urine</span> et n'a aucun intérêt. Toujours s'assurer du <span class=\"kw-clinique\">globe</span> (clinique ± écho) avant tout <span class=\"kw-ttt\">drainage</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 348 — <span class=\"kw-ci\">Insuffisance rénale</span> aiguë - anurie</em></p>","frequence":0},{"id":"347-7","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître le bilan initial d’une rétention d’urine","contenu":"<p>Le diagnostic de RAU est <span class=\"kw-clinique\">clinique</span> : la priorité est le <span class=\"kw-alerte\">drainage en urgence</span>, pas le bilan. La règle change selon la voie de <span class=\"kw-ttt\">drainage</span> et le moment.</p>\n      <div class=\"callout callout-danger\"><strong>Aucun examen complémentaire n'est requis en <span class=\"kw-alerte\">urgence</span> avant un sondage urétral</strong> ❌ : la douleur impose un <span class=\"kw-alerte\">drainage rapide</span>.</div>\n      <h4 class=\"kw-def\">Avant <span class=\"kw-ttt\">drainage</span> — seulement si cathéter sus-pubien envisagé</h4>\n      <ul>\n        <li><span class=\"kw-bio\">Bilan d'hémostase</span> : si suspicion de trouble de l'hémostase ou prise d'<span class=\"kw-ttt\">anticoagulant</span></li>\n        <li><span class=\"kw-imagerie\">Échographie vésicale</span> : indispensable si <span class=\"kw-clinique\">doute clinique</span> (obèse, sujet âgé confus, pathologie neurologique) — confirmer le globe avant de ponctionner</li>\n      </ul>\n      <h4 class=\"kw-def\">Après <span class=\"kw-ttt\">drainage</span> — bilan systématique</h4>\n      <ul>\n        <li><span class=\"kw-bio\">Créatininémie</span>, <span class=\"kw-bio\">ionogramme sanguin</span>, <span class=\"kw-bio\">ECBU</span> : systématiques</li>\n        <li><span class=\"kw-imagerie\">Échographie du haut appareil</span> si <span class=\"kw-alerte\">fièvre</span> (PNA ?) ou <span class=\"kw-alerte\">IRA</span> (dilatation urétéro-pyélo-calicielle ?)</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> On <span class=\"kw-clinique\">draine d'abord</span>, on explore ensuite. Le seul bilan « avant » concerne la <span class=\"kw-clinique\">voie sus-pubienne</span> (hémostase + écho).</div>","frequence":1},{"id":"347-8","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître les indications et les examens biologiques et d’imagerie de première intention","contenu":"<p><span class=\"kw-chiffre\">Première intention</span> = <span class=\"kw-bio\">biologie de retentissement</span> + <span class=\"kw-imagerie\">imagerie ciblée</span>. Le bilan étiologique fin se fait à distance.</p>\n      <h4 class=\"kw-def\">Biologie (1ʳᵉ intention, après <span class=\"kw-ttt\">drainage</span>)</h4>\n      <ul>\n        <li><span class=\"kw-bio\">Créatininémie</span> + <span class=\"kw-bio\">ionogramme sanguin</span> : retentissement rénal et hydroélectrolytique</li>\n        <li><span class=\"kw-bio\">ECBU</span> : systématique (recherche d'infection associée)</li>\n      </ul>\n      <h4 class=\"kw-def\">Imagerie (1ʳᵉ intention)</h4>\n      <table >\n        <thead><tr><th>Examen</th><th>Indication</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-imagerie\"><strong>Échographie vésicale</strong></span></td><td>si <span class=\"kw-clinique\">doute diagnostique</span> (confirmer le globe) ou avant cathéter sus-pubien</td></tr>\n          <tr><td><span class=\"kw-imagerie\"><strong>Échographie du haut appareil</strong></span></td><td>si <span class=\"kw-alerte\">fièvre</span> (PNA ?) ou <span class=\"kw-alerte\">IRA</span> : recherche d'une <span class=\"kw-imagerie\">dilatation pyélo-calicielle</span></td></tr>\n        </tbody>\n      </table>\n      <h4 class=\"kw-def\">Bilan étiologique à distance (pas en <span class=\"kw-alerte\">urgence</span>)</h4>\n      <ul>\n        <li><span class=\"kw-imagerie\">Débitmétrie</span> (systématique, à distance, sans sonde)</li>\n        <li><span class=\"kw-imagerie\">Échographie vésico-prostatique sus-pubienne</span> : <span class=\"kw-clinique\">résidu post-mictionnel</span>, diverticules, épaississement pariétal, lithiase, volume prostatique, tumeur</li>\n        <li><span class=\"kw-imagerie\">Urétrocystoscopie</span> si <span class=\"kw-clinique\">hématurie macroscopique</span> (tumeur ?) ou <span class=\"kw-clinique\">difficultés de sondage</span> (sténose ?)</li>\n        <li><span class=\"kw-imagerie\">UCRM</span> (urétrocystographie rétrograde et mictionnelle) : sténose ou traumatisme urétral</li>\n        <li><span class=\"kw-bio\">Bilan urodynamique</span> : si pathologie <span class=\"kw-etio\">neurologique</span> sous-jacente</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>Logique.</strong> En <span class=\"kw-alerte\">urgence</span> : <span class=\"kw-bio\">créat – iono – ECBU</span> + <span class=\"kw-imagerie\">écho si fièvre/IRA</span>. À distance : on cherche <strong>la cause</strong> (débitmétrie, écho, <span class=\"kw-imagerie\">endoscopie</span>, UCRM, urodynamique).</div>","frequence":0},{"id":"347-9","rang":"A","rubrique":"Identifier une urgence","titre":"Connaître les éléments de gravité en cas de rétention aiguë d’urine","contenu":"<p>La RAU est une <span class=\"kw-alerte\">urgence</span> en soi (douleur, risque de retentissement). Certains éléments imposent une vigilance accrue.</p>\n      <h4 class=\"kw-def\">Éléments de gravité (à rechercher d'emblée)</h4>\n      <table >\n        <thead><tr><th>Élément</th><th>Signification</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-alerte\"><strong>Fièvre</strong></span></td><td>évoque une <span class=\"kw-alerte\">prostatite</span> (<span class=\"kw-bio\">BU</span>/<span class=\"kw-bio\">ECBU</span>) → <span class=\"kw-alerte\">hospitalisation</span> + <span class=\"kw-ttt\">antibiothérapie</span> probabiliste puis adaptée ; risque de <span class=\"kw-alerte\">sepsis</span></td></tr>\n          <tr><td><span class=\"kw-alerte\"><strong>IRA</strong></span></td><td>retentissement sur le haut appareil : <span class=\"kw-imagerie\">dilatation bilatérale des cavités</span> + ↑ <span class=\"kw-bio\">créatininémie</span> ; régresse après <span class=\"kw-ttt\">drainage</span> (dilatation parfois persistante quelques semaines)</td></tr>\n          <tr><td><span class=\"kw-alerte\"><strong>Hématurie</strong></span></td><td><span class=\"kw-bio\">hématurie</span> associée → sondage + lavages par sonde double courant ; bilan étiologique (tumeur ?)</td></tr>\n          <tr><td><span class=\"kw-chiffre\"><strong>Volume vésical élevé</strong></span></td><td><span class=\"kw-def\">pronostic</span> meilleur si <span class=\"kw-chiffre\">&lt; 600 mL</span> ; gros volume → <span class=\"kw-def\">surveillance</span> rapprochée (risque de SLO)</td></tr>\n        </tbody>\n      </table>\n      <h4 class=\"kw-def\">Complications post-<span class=\"kw-ttt\">drainage</span> à prévenir</h4>\n      <table >\n        <thead><tr><th>Complication</th><th>Mécanisme / prévention</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-alerte\"><strong>Syndrome de levée d'obstacle</strong></span> (SLO)</td><td><span class=\"kw-clinique\">polyurie</span> majeure (&gt; <span class=\"kw-chiffre\">1 L/h</span>) après dérivation → <span class=\"kw-bio\">hypokaliémie</span> ++, <span class=\"kw-clinique\">déshydratation</span> pouvant engager le <span class=\"kw-alerte\">pronostic vital</span>. Prévention : <span class=\"kw-clinique\">surveillance horaire de la diurèse</span>, compensation en <span class=\"kw-alerte\">soins intensifs</span></td></tr>\n          <tr><td><span class=\"kw-alerte\"><strong>Hématurie </strong><em>a vacuo</em></span></td><td><span class=\"kw-bio\">hématurie</span> macroscopique si <span class=\"kw-clinique\">vidange trop rapide</span> (favorisée par troubles de l'hémostase / <span class=\"kw-ttt\">anticoagulants</span>). Prévention : contrôle de l'hémostase + <span class=\"kw-clinique\">clampage tous les 300–500 mL / 30 min</span></td></tr>\n          <tr><td><span class=\"kw-alerte\"><strong>Vessie claquée</strong></span></td><td>distension → claquage du détrusor (perte de contractilité) ; justifie d'attendre quelques jours-semaines avant d'ôter une sonde à demeure ; séquelles : diverticules, récidives, rétention chronique</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 158 — <span class=\"kw-clinique\">Sepsis</span> et <span class=\"kw-alerte\">choc septique</span> · 348 — <span class=\"kw-ci\">Insuffisance rénale</span> aiguë - anurie</em></p>","frequence":0},{"id":"347-10","rang":"B","rubrique":"Prise en charge","titre":"Connaître les indications respectives du sondage vésical et du cathétérisme sus-pubien","contenu":"<p>Deux voies de <span class=\"kw-ttt\">drainage</span>. Le <span class=\"kw-clinique\">sondage urétral</span> est la voie de 1ʳᵉ intention ; le <span class=\"kw-clinique\">cathéter sus-pubien</span> intervient en cas d'échec ou de <span class=\"kw-ci\">contre-indication</span>.</p>\n      <table >\n        <thead><tr><th></th><th>Sondage vésical à demeure</th><th>Cathétérisme sus-pubien</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Voie</strong></td><td>voies naturelles (le plus fréquent)</td><td>percutanée sus-pubienne</td></tr>\n          <tr><td><strong>Indication</strong></td><td>1ʳᵉ intention</td><td><span class=\"kw-clinique\">échec</span> ou <span class=\"kw-clinique\">contre-indication</span> au sondage</td></tr>\n          <tr><td><strong>Avantages</strong></td><td>simple, immédiat</td><td>pas de fausse route urétrale ; moins de complications au long cours ; épreuve de clampage possible</td></tr>\n          <tr><td><strong>Risque</strong></td><td><span class=\"kw-clinique\">lésion</span> urétrale → <span class=\"kw-alerte\">sténose</span> secondaire</td><td><span class=\"kw-alerte\">perforation digestive</span> en l'absence de globe</td></tr>\n        </tbody>\n      </table>\n      <h4 class=\"kw-def\"><span class=\"kw-ci\">Contre-indications</span> du sondage urétral</h4>\n      <ul>\n        <li><span class=\"kw-ci\">Sténose urétrale</span></li>\n        <li><span class=\"kw-ci\">Traumatisme de l'urètre</span> (polytraumatisme, fracture du bassin + urétrorragie)</li>\n        <li><span class=\"kw-ci\">Prostatite aiguë</span> : CI <em>relative</em> (possible si apyrétique et après mise en route de l'ATB)</li>\n        <li><span class=\"kw-ci\">Sphincter urinaire artificiel</span> : <span class=\"kw-ci\">CI relative</span> (sonde fine Ch 14, désactivation préalable du système)</li>\n      </ul>\n      <h4 class=\"kw-def\"><span class=\"kw-ci\">Contre-indications</span> du cathéter sus-pubien</h4>\n      <ul>\n        <li><span class=\"kw-ci\">Absence de globe vésical</span> — CI <strong>absolue</strong> (risque de perforation d'une anse intestinale)</li>\n        <li><span class=\"kw-ci\">Pontage extra-anatomique</span> sus-pubien (fémoro-fémoral croisé) — CI <strong>absolue</strong></li>\n        <li>Cicatrice de laparotomie (relative : écho préalable) ; <span class=\"kw-ci\">troubles de l'hémostase / anticoagulants</span></li>\n        <li><span class=\"kw-ci\">ATCD de cancer de vessie</span> (essaimage pariétal) ; <span class=\"kw-ci\">hématurie macroscopique</span></li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>Réflexe d'orientation.</strong> Traumatisme urétral, sténose, <span class=\"kw-clinique\">prostatite</span> fébrile → <span class=\"kw-clinique\">cathéter sus-pubien</span>. Mais d'abord vérifier le <span class=\"kw-clinique\">globe</span> : <strong>pas de globe = pas de cathéter sus-pubien</strong>.</div>","frequence":0},{"id":"347-11","rang":"A","rubrique":"Prise en charge","titre":"Connaître la prise en charge en urgence de la rétention aiguë d’urine","contenu":"<p>La RAU est une <span class=\"kw-alerte\">urgence thérapeutique</span> : le geste clé est le <span class=\"kw-alerte\">drainage vésical en urgence</span>, par sondage urétral à demeure ou cathéter sus-pubien.</p>\n      <h4 class=\"kw-def\">Algorithme de prise en charge</h4>\n      <table >\n        <thead><tr><th>Étape</th><th>Conduite</th></tr></thead>\n        <tbody>\n          <tr><td><strong>1. Confirmation</strong></td><td>diagnostic clinique évident ; si doute → <span class=\"kw-imagerie\">échographie vésicale</span></td></tr>\n          <tr><td><strong>2. Volume vésical</strong></td><td><span class=\"kw-clinique\">globe</span> → <span class=\"kw-alerte\">drainage en URGENCE</span> ; <span class=\"kw-clinique\">vessie vide</span> → chercher une autre étiologie (anurie)</td></tr>\n          <tr><td><strong>3. Modalité</strong></td><td><span class=\"kw-clinique\">sonde urétrale</span> ou <span class=\"kw-clinique\">cathéter sus-pubien</span> (selon <span class=\"kw-clinique\">les</span> CI)</td></tr>\n          <tr><td><strong>4. <span class=\"kw-def\">Surveillance</span></strong></td><td><span class=\"kw-bio\">ECBU</span> des urines évacuées, noter le <span class=\"kw-chiffre\">volume</span>, surveiller la <span class=\"kw-clinique\">diurèse</span>, prévenir le <span class=\"kw-alerte\">SLO</span> et l'<span class=\"kw-alerte\">hématurie a vacuo</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong>Pas d'examen avant le sondage urétral</strong> ❌ : la douleur impose un <span class=\"kw-ttt\">drainage</span> rapide. (Seule la voie sus-pubienne demande hémostase + écho préalables.)</div>\n      <h4 class=\"kw-def\">Sondage urétral à demeure — modalités pratiques</h4>\n      <ul>\n        <li>Asepsie stricte, gel lubrifiant en seringue, <span class=\"kw-clinique\">système clos</span>, <span class=\"kw-ttt\">drainage</span> déclive permanent (éviter la stase)</li>\n        <li>Calibre : éviter <span class=\"kw-clinique\">les</span> petites sondes en 1ʳᵉ intention ❌ ; <span class=\"kw-chiffre\">Ch 18–20</span> chez l'homme (HBP probable) ; sonde <span class=\"kw-clinique\">double courant</span> si <span class=\"kw-bio\">hématurie</span></li>\n        <li>Ballonnet gonflé à <span class=\"kw-chiffre\">8–10 mL</span> d'<span class=\"kw-clinique\">eau pour préparation injectable</span> — <span class=\"kw-ci\">jamais de sérum physiologique</span> (le NaCl cristallise et bloque le dégonflage)</li>\n        <li>Toujours <span class=\"kw-clinique\">recalotter</span> le patient en fin de geste (risque de <span class=\"kw-alerte\">paraphimosis</span>)</li>\n      </ul>\n      <h4 class=\"kw-def\">Après le <span class=\"kw-ttt\">drainage</span></h4>\n      <ul>\n        <li><strong>Bilan :</strong> <span class=\"kw-bio\">créatininémie, ionogramme, ECBU</span> ; <span class=\"kw-imagerie\">écho du haut appareil</span> si <span class=\"kw-clinique\">fièvre</span>/IRA</li>\n        <li><strong>Prévention du SLO :</strong> <span class=\"kw-clinique\">surveillance horaire de la diurèse</span> ; compensation hydroélectrolytique en <span class=\"kw-alerte\">soins intensifs</span> si polyurie</li>\n        <li><strong>Prévention de l'<span class=\"kw-bio\">hématurie</span> a vacuo :</strong> bilan d'hémostase, vidange lente, <span class=\"kw-clinique\">clampage 300–500 mL / 30 min</span></li>\n        <li><strong><span class=\"kw-def\">Surveillance</span> :</strong> noter le volume retiré (<span class=\"kw-def\">pronostic</span> meilleur si <span class=\"kw-chiffre\">&lt; 600 mL</span>), diurèse horaire</li>\n      </ul>\n      <h4 class=\"kw-def\">Épreuve d'ablation de sonde</h4>\n      <ul>\n        <li>Prévue <span class=\"kw-clinique\">quelques jours après</span> l'épisode, une fois la cause diagnostiquée et traitée</li>\n        <li><span class=\"kw-ttt\">α-bloquant</span> chez l'homme (majore <span class=\"kw-clinique\">les</span> chances de reprise mictionnelle, surtout si HBP impliquée)</li>\n        <li>Mesure du <span class=\"kw-clinique\">résidu post-mictionnel</span> lors de l'épreuve</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>Trois réflexes ⭐⭐.</strong> (1) Drainer <span class=\"kw-clinique\">en urgence</span> ; (2) <span class=\"kw-ci\">eau</span> pour le ballonnet, <span class=\"kw-ci\">jamais de</span> NaCl ; (3) après <span class=\"kw-ttt\">drainage</span>, <span class=\"kw-clinique\">surveillance horaire de la diurèse</span> (SLO) + clampage si vidange rapide (<span class=\"kw-bio\">hématurie</span> a vacuo).</div>","frequence":2}],"astuces":[],"strategie":{"urgence":"<p><strong>Degré :</strong> <span class=\"kw-alerte\">urgence urologique</span> — toute rétention aiguë d'urine impose un <span class=\"kw-ttt\">drainage vésical en urgence</span><br><strong>1er geste :</strong> confirmer le <span class=\"kw-clinique\">globe vésical</span> puis assurer le <span class=\"kw-ttt\">drainage des urines</span> (sondage urétral à demeure ou cathéter sus-pubien)<br><strong>Fenêtre :</strong> <span class=\"kw-ttt\">drainage</span> le plus rapide possible — la <span class=\"kw-clinique\">douleur</span> impose l'évacuation sans délai<br><strong>Avant le geste :</strong> <span class=\"kw-chiffre\">aucun examen complémentaire</span> n'est requis en <span class=\"kw-alerte\">urgence</span> avant un sondage urétral</p>","hospit":"<p><strong>Sur place :</strong> <span class=\"kw-ttt\">drainage vésical en urgence</span> dès la confirmation du globe<br><strong><span class=\"kw-alerte\">Hospitalisation</span> :</strong> si <span class=\"kw-clinique\">fièvre</span> → recherche d'une <span class=\"kw-etio\">prostatite aiguë</span> (<span class=\"kw-bio\">BU/ECBU</span>) + <span class=\"kw-ttt\">antibiothérapie</span> probabiliste puis adaptée<br><strong><span class=\"kw-alerte\">Soins intensifs</span> :</strong> en cas de <span class=\"kw-alerte\">syndrome de levée d'obstacle</span> (polyurie majeure) — <span class=\"kw-def\">surveillance</span> et compensation hydroélectrolytique<br><strong>Imagerie :</strong> <span class=\"kw-imagerie\">échographie du haut appareil</span> si <span class=\"kw-clinique\">fièvre</span> ou <span class=\"kw-etio\">insuffisance rénale aiguë</span></p>","redflags":"<ul><li><span class=\"kw-clinique\">Fièvre</span>, <span class=\"kw-clinique\">frissons</span> → suspicion de <span class=\"kw-etio\">prostatite aiguë</span>, risque de <span class=\"kw-alerte\">sepsis</span></li><li>Retentissement sur le haut appareil : <span class=\"kw-radio\">dilatation bilatérale des voies excrétrices supérieures</span> et/ou <span class=\"kw-bio\">élévation de la créatininémie</span> (<span class=\"kw-etio\">insuffisance rénale aiguë obstructive</span>)</li><li><span class=\"kw-clinique\">Hématurie macroscopique</span> → risque de <span class=\"kw-etio\">caillotage vésical</span></li><li>Volume de rétention <span class=\"kw-chiffre\">> 600 mL</span> (<span class=\"kw-def\">pronostic</span> de reprise mictionnelle moins favorable)</li><li>Après <span class=\"kw-ttt\">drainage</span> : <span class=\"kw-alerte\">syndrome de levée d'obstacle</span> — <span class=\"kw-clinique\">polyurie</span> <span class=\"kw-chiffre\">> 1 L/h</span>, <span class=\"kw-bio\">hypokaliémie</span>, <span class=\"kw-clinique\">déshydratation</span> pouvant engager le <span class=\"kw-alerte\">pronostic vital</span></li><li><span class=\"kw-alerte\">Hématurie a vacuo</span> en cas de <span class=\"kw-alerte\">vidange vésicale trop rapide</span> (favorisée par <span class=\"kw-clinique\">les</span> <span class=\"kw-ttt\">anticoagulants</span>)</li></ul>","principes":"<p><span class=\"kw-ttt\">Drainage vésical en urgence</span>, puis bilan et traitement de la cause. Le choix de la voie de <span class=\"kw-ttt\">drainage</span> dépend des <span class=\"kw-ci\">contre-indications</span>.</p><p><strong>Sondage urétral à demeure (1re intention)</strong></p><p>CI : <span class=\"kw-ci\">sténose urétrale</span>, <span class=\"kw-ci\">traumatisme de l'urètre</span>, <span class=\"kw-ci\">prostatite aiguë</span> (relative), <span class=\"kw-ci\">sphincter urinaire artificiel</span> (relative)</p><ul><li>Voie naturelle, méthode la plus fréquente et la plus simple</li><li>Éviter <span class=\"kw-clinique\">les</span> <span class=\"kw-ci\">sondes de petit calibre</span> en 1re intention ; <span class=\"kw-ttt\">Charrière 18-20</span> chez l'homme susceptible d'HBP (sonde plus rigide, plus facile à introduire)</li><li>Sonde à <span class=\"kw-ttt\">double courant</span> si <span class=\"kw-clinique\">hématurie macroscopique</span> (irr<span class=\"kw-chiffre\">iga</span>tion)</li><li>Ballonnet gonflé à l'<span class=\"kw-ttt\">eau pour préparation injectable</span> : pas de <span class=\"kw-ci\">sérum physiologique</span> (le NaCl cristallise et empêche le dégonflage)</li><li>Toujours <span class=\"kw-ttt\">recalotter</span> en fin de geste (risque de <span class=\"kw-alerte\">paraphimosis</span>)</li></ul><p><strong>Cathéter sus-pubien (échec ou CI du sondage)</strong></p><p><span class=\"kw-ci\">CI absolue</span> : <span class=\"kw-ci\">absence de globe vésical</span>, <span class=\"kw-ci\">pontage vasculaire sus-pubien</span> ; CI : <span class=\"kw-ci\">ATCD de cancer de vessie</span>, <span class=\"kw-ci\">hématurie macroscopique</span>, <span class=\"kw-ci\">anticoagulant</span></p><ul><li>Voie <span class=\"kw-ttt\">percutanée</span>, indiquée en cas d'<span class=\"kw-etio\">échec</span> ou de <span class=\"kw-ci\">contre-indication au sondage urétral</span></li><li>Toujours <span class=\"kw-imagerie\">s'assurer de l'existence d'un globe vésical</span> avant la pose (<span class=\"kw-imagerie\">échographie vésicale</span> si doute : obèse, sujet âgé confus, contexte neurologique)</li><li><span class=\"kw-bio\">Bilan d'hémostase</span> préalable si <span class=\"kw-ttt\">anticoagulant</span> ou trouble de l'hémostase</li><li>Avantages : pas de fausse route urétrale, épreuve de clampage possible pour juger de la reprise mictionnelle</li></ul><p><strong>Traitement étiologique</strong></p><ul><li><span class=\"kw-etio\">HBP</span> : <span class=\"kw-ttt\">α-bloquant</span> ; ablation de sonde tentée après <span class=\"kw-chiffre\">48 h</span> ; <span class=\"kw-ttt\">chirurgie</span> si échec de désondage ou HBP compliquée/sévère</li><li><span class=\"kw-etio\">Prostatite aiguë</span> : <span class=\"kw-ttt\">drainage</span> préférentiel par <span class=\"kw-ttt\">cathéter sus-pubien</span> + <span class=\"kw-ttt\">C3G IV ou fluoroquinolone</span> probabiliste puis ATB adaptée <span class=\"kw-chiffre\">14-21 jours</span></li><li><span class=\"kw-etio\">Caillotage vésical</span> : <span class=\"kw-ttt\">sonde double courant de gros calibre (22-24)</span> + lavage vésical continu, décaillotage si besoin</li><li><span class=\"kw-etio\">Sténose ou traumatisme de l'urètre</span> : <span class=\"kw-ttt\">cathéter sus-pubien</span> d'emblée (<span class=\"kw-ci\">sondage urétral contre-indiqué</span>), bilan par <span class=\"kw-imagerie\">UCRM</span></li><li><span class=\"kw-etio\">Phimosis serré</span> : cathéter sus-pubien si sondage impossible, <span class=\"kw-ttt\">circoncision</span> dans un 2nd temps ; <span class=\"kw-etio\">prolapsus génital</span> : réduire le prolapsus</li></ul>","suivi":"<p><strong>Immédiat :</strong> noter le <span class=\"kw-clinique\">volume évacué</span> (<span class=\"kw-chiffre\">meilleur pronostic si &lt; 600 mL</span>), <span class=\"kw-bio\">ECBU</span> sur <span class=\"kw-clinique\">les</span> urines, <span class=\"kw-def\">suivi</span> de la <span class=\"kw-clinique\">diurèse horaire</span><br><strong>Levée d'obstacle :</strong> prévenir le <span class=\"kw-alerte\">syndrome de levée d'obstacle</span> — <span class=\"kw-def\">surveillance</span> horaire de la diurèse, <span class=\"kw-bio\">ionogrammes sanguin et urinaire</span> réguliers, compensation en solutés<br><strong><span class=\"kw-bio\">Hématurie</span> a vacuo :</strong> prévenir par une vidange lente, <span class=\"kw-ttt\">clampage tous les 300-500 mL / 30 min</span>, contrôle préalable de l'<span class=\"kw-bio\">hémostase</span><br><strong>Reprise mictionnelle :</strong> <span class=\"kw-ttt\">épreuve d'ablation de sonde</span> quelques jours après, sous <span class=\"kw-ttt\">α-bloquant</span> chez l'homme, avec mesure du <span class=\"kw-clinique\">résidu post-mictionnel</span><br><strong>Bilan à distance :</strong> <span class=\"kw-imagerie\">débitmétrie</span>, <span class=\"kw-imagerie\">échographie vésico-prostatique</span> ; <span class=\"kw-imagerie\">urétrocystoscopie</span> si <span class=\"kw-bio\">hématurie</span> ou difficulté de sondage ; <span class=\"kw-imagerie\">bilan urodynamique</span> si cause neurologique</p>"},"liensGlobaux":[{"href":"https://www.urofrance.org/lafu-academie/formation-du-college/referentiel-du-college-durologie-6eme-edition/chapitre-20-item-347-retention-aigue-durine/","label":"Collège : Référentiel d'Urologie — chapitre 20 (item 347)"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Suspicion de rétention aiguë d'urine — Impossibilité totale et brutale d'uriner malgré la réplétion vésicale, avec envie pressante et douloureuse d'uriner","detail":"<h4>CAT — Rétention aiguë d'urine — De la confirmation du globe au <span class=\"kw-ttt\">drainage</span> en <span class=\"kw-alerte\">urgence</span> et à sa <span class=\"kw-def\">surveillance</span></h4>","branches":[{"to":"q-confirm","label":"Confirmation diagnostique","color":"blue"}]},{"id":"q-confirm","kind":"decision","label":"Globe vésical présent ? — Masse sus-pubienne douloureuse, mate à la percussion ; échographie vésicale si doute (obèse, sujet âgé confus, contexte neurologique)","branches":[{"to":"t-anurie","label":"Vessie vide (diurèse &lt; 200 mL/24h)","color":"blue"},{"to":"q-gravite","label":"Globe présent","color":"green"}]},{"id":"t-anurie","kind":"terminal","label":"Ce n'est pas une RAU — ré-orienter","color":"blue","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Pas de globe vésical</span>, vessie vide à l'<span class=\"kw-imagerie\">échographie</span></li></ul><h4>Conduite</h4><ul><li>Évoquer une <span class=\"kw-etio\">anurie</span> (absence de filtration glomérulaire) : <span class=\"kw-chiffre\">diurèse &lt; 200 mL/24h</span></li><li>Rechercher une autre étiologie au tableau</li></ul>"},{"id":"q-gravite","kind":"decision","label":"Signe de gravité associé ? — Fièvre, IRA / dilatation des voies excrétrices, hématurie macroscopique, volume > 600 mL","branches":[{"to":"t-hospit","label":"Oui","color":"red"},{"to":"q-ci-sondage","label":"Non","color":"green"}]},{"id":"t-hospit","kind":"terminal","label":"Drainage en urgence + hospitalisation","color":"red","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Fièvre</span> → <span class=\"kw-etio\">prostatite aiguë</span> ; <span class=\"kw-radio\">dilatation bilatérale des voies excrétrices</span> et/ou <span class=\"kw-bio\">créatininémie élevée</span> → <span class=\"kw-etio\">IRA obstructive</span></li></ul><h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Drainage vésical en urgence</span> ; si <span class=\"kw-clinique\">prostatite</span>, <span class=\"kw-ttt\">drainage</span> préférentiel par <span class=\"kw-ttt\">cathéter sus-pubien</span></li></ul><h4>Traitement</h4><ul><li>Si <span class=\"kw-clinique\">prostatite</span> : <span class=\"kw-ttt\">C3G IV ou fluoroquinolone</span> probabiliste puis ATB adaptée <span class=\"kw-chiffre\">14-21 jours</span></li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li><span class=\"kw-imagerie\">Échographie du haut appareil</span> si <span class=\"kw-clinique\">fièvre</span> ou IRA</li><li><span class=\"kw-alerte\">Soins intensifs</span> si <span class=\"kw-alerte\">syndrome de levée d'obstacle</span> (polyurie <span class=\"kw-chiffre\">> 1 L/h</span>, <span class=\"kw-bio\">hypokaliémie</span>)</li></ul>"},{"id":"q-ci-sondage","kind":"decision","label":"CI ou échec du sondage urétral ? — Sténose urétrale, traumatisme de l'urètre, prostatite aiguë fébrile, sphincter urinaire artificiel","branches":[{"to":"t-sonde","label":"Non","color":"green"},{"to":"t-csp","label":"Oui ou échec du sondage","color":"amber"}]},{"id":"t-sonde","kind":"terminal","label":"Sondage urétral à demeure en urgence","color":"green","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Drainage</span> immédiat par voie naturelle ; éviter <span class=\"kw-clinique\">les</span> <span class=\"kw-ci\">sondes de petit calibre</span>, <span class=\"kw-ttt\">Charrière 18-20</span> si HBP</li><li>Sonde à <span class=\"kw-ttt\">double courant</span> si <span class=\"kw-clinique\">hématurie macroscopique</span></li></ul><h4>Traitement</h4><ul><li>Ballonnet gonflé à l'<span class=\"kw-ttt\">eau pour préparation injectable</span> (pas de <span class=\"kw-ci\">sérum physiologique</span> → cristallisation du NaCl)</li><li><span class=\"kw-ttt\">Recalotter</span> en fin de geste (<span class=\"kw-alerte\">paraphimosis</span>)</li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li>Noter le <span class=\"kw-clinique\">volume évacué</span> (<span class=\"kw-chiffre\">meilleur pronostic si &lt; 600 mL</span>), <span class=\"kw-bio\">ECBU</span>, <span class=\"kw-clinique\">diurèse horaire</span></li></ul>"},{"id":"t-csp","kind":"terminal","label":"Cathéter sus-pubien (voie percutanée) — Échec ou contre-indication au sondage urétral","color":"amber","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Cathéter sus-pubien</span> par voie percutanée</li><li>Toujours <span class=\"kw-imagerie\">s'assurer du globe vésical</span> avant la pose (<span class=\"kw-imagerie\">échographie</span> si doute)</li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-bio\">Bilan d'hémostase</span> si <span class=\"kw-ttt\">anticoagulant</span> ou trouble de l'hémostase</li></ul><h4><span class=\"kw-ci\">Contre-indications</span></h4><ul><li>Absolues : <span class=\"kw-ci\">absence de globe vésical</span>, <span class=\"kw-ci\">pontage vasculaire sus-pubien</span></li><li>Relatives : <span class=\"kw-ci\">ATCD de cancer de vessie</span>, <span class=\"kw-ci\">hématurie macroscopique</span>, <span class=\"kw-ci\">anticoagulant</span></li></ul>"}]},"cards":[{"i":"5ae165255a40","n":347,"o":"347-1","u":"Définition","t":"Connaître la définition de la rétention aiguë d’urine","q":"Quel est le mécanisme caractéristique de la rétention aiguë d'urine (RAU) ?","a":"<p>Le mécanisme caractéristique est un <strong>blocage total et brutal de la vidange</strong> urinaire, entraînant une <strong>vessie pleine et sous tension</strong>.</p>"},{"i":"66498bf543fb","n":347,"o":"347-1","u":"Définition","t":"Connaître la définition de la rétention aiguë d’urine","q":"Comment différencier une rétention aiguë d'urine (RAU) d'une anurie ?","a":"<p>La RAU se caractérise par une <strong>vessie pleine</strong> (globe vésical), tandis que l'anurie correspond à l'absence d'urines dans une <strong>vessie vide</strong>.</p>"},{"i":"ae73aa65f7e0","n":347,"o":"347-1","u":"Définition","t":"Connaître la définition de la rétention aiguë d’urine","q":"Quels sont les principaux signes cliniques d'une rétention aiguë d'urine (RAU) ?","a":"<ul><li>Le patient est <strong>algique</strong>, <strong>anxieux</strong> et <strong>agité</strong>.</li><li>Il présente une <strong>envie permanente d'uriner</strong>.</li><li>Le signe physique majeur est le <strong>globe vésical</strong> : une masse sus-pubienne douloureuse, tendue et mate à la percussion.</li></ul>"},{"i":"d7ee3aeeee29","n":347,"o":"347-1","u":"Définition","t":"Connaître la définition de la rétention aiguë d’urine","q":"Quelle est la définition de la rétention aiguë d'urine (RAU) ?","a":"<p>La rétention aiguë d'urine (RAU) se définit comme l'<strong>impossibilité totale et brutale d'uriner</strong> malgré la <strong>réplétion vésicale</strong>, accompagnée d'une <strong>envie pressante et douloureuse</strong> d'uriner.</p>"},{"i":"6d7cf7104692","n":347,"o":"347-11","u":"Prise en charge","t":"Connaître la prise en charge en urgence de la rétention aiguë d’urine","q":"Quelles sont les étapes de la prise en charge d'urgence d'une rétention aiguë d'urine ?","a":"<ul><li><strong>Confirmation diagnostique</strong> : clinique évidente ; si doute, <strong>échographie vésicale</strong>.</li><li><strong>Volume vésical</strong> : si globe vésical, drainage en urgence ; si vessie vide, chercher une autre étiologie (ex : anurie).</li><li><strong>Modalité de drainage</strong> : sonde urétrale ou cathéter sus-pubien (en fonction des contre-indications).</li><li><strong>Surveillance post-drainage</strong> : ECBU, volume urinaire évacué, diurèse, prévention du syndrome de levée d'obstacle (SLO) et de l'hématurie a vacuo.</li></ul>"},{"i":"8cb60fa6d284","n":347,"o":"347-11","u":"Prise en charge","t":"Connaître la prise en charge en urgence de la rétention aiguë d’urine","q":"Quels sont les examens complémentaires à réaliser après le drainage d'une rétention aiguë d'urine et quelles sont les surveillances essentielles ?","a":"<ul><li><strong>Bilan biologique</strong> : créatininémie, ionogramme sanguin, ECBU.</li><li><strong>Échographie du haut appareil</strong> si fièvre et/ou insuffisance rénale aiguë.</li><li><strong>Prévention du syndrome de levée d'obstacle (SLO)</strong> : surveillance horaire de la diurèse, compensation hydroélectrolytique si polyurie.</li><li><strong>Prévention de l'hématurie a vacuo</strong> : bilan d'hémostase (si contexte), <strong>clampage de la sonde</strong> avec vidange lente (300-500 mL par 30 minutes).</li><li><strong>Surveillance</strong> : noter le volume retiré (meilleur pronostic si <strong>moins de 600 mL</strong>), diurèse horaire.</li></ul>"},{"i":"d3e4c14e1471","n":347,"o":"347-11","u":"Prise en charge","t":"Connaître la prise en charge en urgence de la rétention aiguë d’urine","q":"Quelle est l'attitude initiale face à une rétention aiguë d'urine (RAU) aux urgences ?","a":"<p>La rétention aiguë d'urine est une <strong>urgence thérapeutique</strong>. Le geste clé est le <strong>drainage vésical en urgence</strong>, le plus souvent par sondage urétral à demeure ou, si besoin, par cathéter sus-pubien.</p>"},{"i":"f21fc26041ac","n":347,"o":"347-11","u":"Prise en charge","t":"Connaître la prise en charge en urgence de la rétention aiguë d’urine","q":"Quelles sont les bonnes pratiques lors d'un sondage urétral pour une rétention aiguë d'urine ?","a":"<ul><li>Respecter une <strong>asepsie stricte</strong> et utiliser un <strong>gel lubrifiant</strong> anesthésiant.</li><li>Utiliser un <strong>système clos</strong> et un drainage déclive permanent.</li><li>Privilégier un calibre de sonde de <strong>Ch 18-20</strong> chez l'homme (éviter les petites sondes en 1<sup>re</sup> intention).</li><li>Gonfler le ballonnet avec <strong>8 à 10 mL d'eau pour préparation injectable</strong> (jamais de sérum physiologique).</li><li>Toujours <strong>recalotter le patient</strong> en fin de geste pour éviter un paraphimosis.</li><li>En cas d'hématurie, utiliser une sonde <strong>double courant</strong>.</li></ul>"},{"i":"fa7799d7dd40","n":347,"o":"347-11","u":"Prise en charge","t":"Connaître la prise en charge en urgence de la rétention aiguë d’urine","q":"Quand et comment est envisagée l'épreuve d'ablation de sonde après une rétention aiguë d'urine ?","a":"<p>L'épreuve d'ablation de sonde est prévue <strong>quelques jours après l'épisode</strong> de RAU, une fois la cause diagnostiquée et traitée. Elle est souvent facilitée par l'administration d'<strong>alpha-bloquants</strong> chez l'homme, surtout si une hyperplasie bénigne de la prostate est impliquée. La mesure du <strong>résidu post-mictionnel</strong> est évaluée lors de cette épreuve.</p>"},{"i":"48b418f02ba5","n":347,"o":"347-3","u":"Etiologie","t":"Connaître les principales causes de rétention aiguë d’urine","q":"Quelles sont les principales classes de médicaments et molécules pouvant induire une rétention aiguë d'urine ?","a":"<p>Les principales classes de médicaments et molécules pouvant induire une rétention aiguë d'urine sont :</p><ul><li>les <strong>anticholinergiques</strong> (risque augmenté si RPM > 100 mL) : collyres mydriatiques (<strong>atropine</strong>, cyclopentolate, tropicamide), anticholinergiques vésicaux (oxybutynine, toltérodine, trospium), neuroleptiques phénothiaziniques, antidépresseurs tricycliques, certains antiparkinsoniens, néfopam, tiémonium, antihistaminiques (hydroxyzine).</li><li>les <strong>morphiniques</strong>, notamment en rachianesthésie/péridurale, ou à fortes doses.</li><li>d'autres médicaments moins fréquents : <strong>inhibiteurs calciques</strong>, <strong>β-2-mimétiques</strong> (salbutamol, terbutaline), <strong>sympathomimétiques</strong> (pseudo-éphédrine, phényléphrine, éphédrine).</li></ul>"},{"i":"bd753bac8817","n":347,"o":"347-3","u":"Etiologie","t":"Connaître les principales causes de rétention aiguë d’urine","q":"Quelles sont les principales causes mécaniques de rétention aiguë d'urine (RAU) chez l'homme adulte ?","a":"<p>Chez l'homme adulte, les principales causes mécaniques (obstacle sous-vésical) de rétention aiguë d'urine sont :</p><ul><li>l'<strong>hyperplasie bénigne de la prostate (HBP)</strong>, qui est la cause n°1, le risque étant majoré par l'âge et la sévérité des symptômes (IPSS > 7).</li><li>la <strong>prostatite aiguë</strong>.</li><li>la <strong>sténose de l'urètre</strong> (post-traumatique, post-infectieuse, iatrogène).</li><li>le <strong>traumatisme de l'urètre</strong>, souvent lié à un polytraumatisme avec fracture du bassin et urétrorragie.</li><li>le <strong>caillotage vésical</strong>.</li><li>le <strong>cancer de la prostate</strong>, si localement avancé (T3-T4).</li><li>un <strong>calcul vésical</strong>.</li><li>un <strong>phimosis serré</strong>.</li></ul>"},{"i":"d6afab4c25d0","n":347,"o":"347-3","u":"Etiologie","t":"Connaître les principales causes de rétention aiguë d’urine","q":"Quelles sont les principales causes fonctionnelles de rétention aiguë d'urine ?","a":"<p>Les principales causes fonctionnelles de rétention aiguë d'urine comprennent :</p><ul><li>les causes <strong>neurologiques centrales</strong> : <strong>SEP</strong>, compression ou lésion médullaire, maladie de <strong>Parkinson</strong>, <strong>AVC</strong>, lésions congénitales de la moelle comme le spina-bifida.</li><li>les causes <strong>neurologiques périphériques</strong> : <strong>diabète</strong>, chirurgie d'exentération pelvienne (rectum, utérus).</li><li>d'autres causes fonctionnelles : <strong>cystite aiguë</strong>, <strong>vulvo-vaginite herpétique</strong> (chez la femme), <strong>fécalome</strong> ou <strong>hémorroïdes</strong> (par réflexes liés à une pathologie anorectale).</li></ul>"},{"i":"0dd2a7f586f9","n":347,"o":"347-4","u":"Diagnostic positif","t":"Connaître les éléments cliniques de la rétention aiguë d’urine","q":"Quels examens physiques complémentaires doivent être réalisés à la recherche d'une étiologie de la rétention aiguë d'urine ?","a":"<p>Il convient de réaliser :</p><ul><li>Un <strong>toucher rectal</strong> : à la recherche d'une prostate douloureuse (prostatite aiguë), d'un fécalome ou d'une pathologie de l'ampoule rectale (hémorroïdes, tumeur).</li><li>Un <strong>toucher vaginal</strong> chez la femme : à la recherche d'une tumeur gynécologique, d'un prolapsus génital ou pour évaluer la trophicité des tissus.</li><li>Un <strong>examen des organes génitaux externes</strong> (OGE) : pour dépister un phimosis serré, une sténose du méat urétral ou une orchi-épididymite.</li></ul>"},{"i":"0e96d68ca23c","n":347,"o":"347-4","u":"Diagnostic positif","t":"Connaître les éléments cliniques de la rétention aiguë d’urine","q":"Décrivez les caractéristiques cliniques du globe vésical lors d'une rétention aiguë d'urine.","a":"<p>Le globe vésical est le <strong>signe physique majeur</strong> de la rétention aiguë d'urine. Il se manifeste par :</p><ul><li>Une <strong>masse sus-pubienne douloureuse et tendue</strong>.</li><li>La palpation de cette masse <strong>augmente l'envie d'uriner</strong>.</li><li>Une <strong>voussure à convexité supérieure</strong>.</li><li>Une <strong>matité à la percussion</strong> de la région sus-pubienne.</li></ul>"},{"i":"ba91b0dd46bd","n":347,"o":"347-4","u":"Diagnostic positif","t":"Connaître les éléments cliniques de la rétention aiguë d’urine","q":"Quels sont les antécédents médicaux à rechercher lors de l'interrogatoire d'un patient présentant une rétention aiguë d'urine ?","a":"<p>Il faut rechercher :</p><ul><li>Des <strong>antécédents urologiques</strong> : rétention aiguë d'urine (RAU), hyperplasie bénigne de la prostate (HBP), cancer de la prostate/vessie, prostatite, infection urinaire, sténose urétrale, chirurgie endoscopique ou sondages.</li><li>Des <strong>antécédents neurologiques</strong> : lésion médullaire, sclérose en plaques (SEP), spina-bifida, maladie de Parkinson, diabète, accident vasculaire cérébral (AVC).</li><li>Les <strong>traitements en cours</strong>, notamment ceux inducteurs de RAU ou les anti-thrombotiques.</li></ul>"},{"i":"c4ae913df873","n":347,"o":"347-4","u":"Diagnostic positif","t":"Connaître les éléments cliniques de la rétention aiguë d’urine","q":"Comment pose-t-on le diagnostic de rétention aiguë d'urine (RAU) sur le plan clinique ?","a":"<p>Le diagnostic de rétention aiguë d'urine est <strong>clinique</strong>, reposant sur l'association d'un tableau <strong>douloureux brutal</strong> et de la présence d'un <strong>globe vésical</strong>.</p>"},{"i":"fa7c5e0ed175","n":347,"o":"347-4","u":"Diagnostic positif","t":"Connaître les éléments cliniques de la rétention aiguë d’urine","q":"Quels sont les signes fonctionnels caractéristiques de la rétention aiguë d'urine ?","a":"<ul><li>Le patient est <strong>algique</strong>, <strong>anxieux</strong> et <strong>agité</strong>.</li><li>Il présente une <strong>envie permanente et douloureuse d'uriner</strong>.</li><li>Il y a une <strong>impossibilité totale et brutale d'uriner</strong>.</li></ul>"},{"i":"2d74b3c6567e","n":347,"o":"347-6","u":"Diagnostic positif","t":"Connaître les signes cliniques distinguant la rétention aiguë d’urine de l’anurie","q":"Comment différencier cliniquement une rétention aiguë d'urine (RAU) d'une anurie quant à l'état de la vessie ?","a":"<p>La rétention aiguë d'urine se caractérise par une <strong>vessie pleine</strong>, palpable sous la forme d'un <strong>globe vésical</strong> (masse sus-pubienne, mate à la percussion, douloureuse). À l'inverse, l'anurie présente une <strong>vessie vide</strong>, sans globe vésical palpable.</p>"},{"i":"56faee61e7d9","n":347,"o":"347-6","u":"Diagnostic positif","t":"Connaître les signes cliniques distinguant la rétention aiguë d’urine de l’anurie","q":"Quelles sont les caractéristiques de l'envie d'uriner en cas de rétention aiguë d'urine et d'anurie ?","a":"<p>En cas de rétention aiguë d'urine, l'envie d'uriner est <strong>impérieuse et douloureuse</strong>. En cas d'anurie, elle est <strong>absente</strong>.</p>"},{"i":"8df0b2ce2957","n":347,"o":"347-6","u":"Diagnostic positif","t":"Connaître les signes cliniques distinguant la rétention aiguë d’urine de l’anurie","q":"Quelle est la principale différence de mécanisme entre la rétention aiguë d'urine et l'anurie ?","a":"<p>La rétention aiguë d'urine est un <strong>obstacle à l'évacuation</strong> de l'urine de la vessie. L'anurie est un <strong>défaut de filtration glomérulaire</strong>, entraînant une absence de production d'urine par les reins.</p>"},{"i":"26bfe76e001a","n":347,"o":"347-7","u":"Examens complémentaires","t":"Connaître le bilan initial d’une rétention d’urine","q":"Quels examens complémentaires sont indiqués avant un drainage vésical en cas de rétention aiguë d'urine (RAU) et dans quelles situations spécifiques ?","a":"<p>Avant un drainage vésical par voie urétrale, <strong>aucun examen complémentaire n'est requis en urgence</strong>. Cependant, si un drainage par <strong>cathétérisme sus-pubien</strong> est envisagé, les examens suivants sont nécessaires :</p><ul><li>Un <strong>bilan d'hémostase</strong> : si la suspicion d'un trouble de l'hémostase existe ou si le patient est sous traitement anticoagulant.</li><li>Une <strong>échographie vésicale</strong> : indispensable si un doute clinique persiste (patient obèse, sujet âgé confus, pathologie neurologique) pour confirmer la présence du globe vésical avant la ponction.</li></ul>"},{"i":"932d46298530","n":347,"o":"347-7","u":"Examens complémentaires","t":"Connaître le bilan initial d’une rétention d’urine","q":"Quels sont les examens complémentaires systématiques à réaliser après le drainage d'une rétention aiguë d'urine (RAU) ?","a":"<p>Après le drainage d'une rétention aiguë d'urine (RAU), un bilan systématique doit être réalisé :</p><ul><li>La <strong>créatininémie</strong> et l'<strong>ionogramme sanguin</strong>.</li><li>Un <strong>ECBU</strong> (Examen CytoBactériologique des Urines).</li></ul><p>Une <strong>échographie du haut appareil urinaire</strong> est également indiquée en cas de <strong>fièvre</strong> (pour rechercher une pyélonéphrite aiguë) ou d'<strong>insuffisance rénale aiguë</strong> (pour évaluer une dilatation urétéro-pyélo-calicielle).</p>"},{"i":"b40217ea3a79","n":347,"o":"347-7","u":"Examens complémentaires","t":"Connaître le bilan initial d’une rétention d’urine","q":"Quel est l'examen prioritaire à réaliser en cas de rétention aiguë d'urine (RAU) avérée, et pourquoi ?","a":"<p>En cas de rétention aiguë d'urine (RAU), la priorité absolue est le <strong>drainage</strong> de la vessie en urgence, car la douleur est intense. Le bilan initial est réalisé après cette étape.</p>"},{"i":"4107a529eaa4","n":347,"o":"347-8","u":"Examens complémentaires","t":"Connaître les indications et les examens biologiques et d’imagerie de première intention","q":"Quels sont les examens biologiques de première intention à réaliser après drainage d'une rétention aiguë d'urine ?","a":"<p>Après drainage d'une rétention aiguë d'urine, les examens biologiques de première intention à réaliser sont :</p><ul><li>La <strong>créatininémie</strong> et l'<strong>ionogramme sanguin</strong> : pour évaluer un retentissement rénal et hydroélectrolytique.</li><li>L'<strong>ECBU</strong> (Examen CytoBactériologique des Urines) : systématique, pour rechercher une infection urinaire associée.</li></ul>"},{"i":"4b05bef06b1f","n":347,"o":"347-8","u":"Examens complémentaires","t":"Connaître les indications et les examens biologiques et d’imagerie de première intention","q":"Dans quels cas réalise-t-on une échographie du haut appareil en première intention face à une rétention aiguë d'urine ?","a":"<p>Une échographie du haut appareil est réalisée en première intention si le patient présente de la <strong>fièvre</strong> (pour rechercher une pyélonéphrite aiguë) ou une <strong>IRA</strong> (Insuffisance Rénale Aiguë), afin de rechercher une <strong>dilatation pyélo-calicielle</strong>.</p>"},{"i":"c3e3b44f2b45","n":347,"o":"347-8","u":"Examens complémentaires","t":"Connaître les indications et les examens biologiques et d’imagerie de première intention","q":"Quelle est l'indication de l'échographie vésicale en première intention dans la rétention aiguë d'urine ?","a":"<p>L'échographie vésicale est indiquée en première intention en cas de <strong>doute diagnostique</strong> pour confirmer la présence d'un globe vésical, ou avant la pose d'un <strong>cathéter sus-pubien</strong>.</p>"},{"i":"0bdb0965fb9f","n":347,"o":"347-9","u":"Identifier une urgence","t":"Connaître les éléments de gravité en cas de rétention aiguë d’urine","q":"Quel est le risque particulier en cas de gros volume vésical lors d'une rétention aiguë d'urine (RAU) et après drainage ?","a":"<p>Un <strong>gros volume vésical</strong> (notamment supérieur à 600 mL) est associé à un pronostic moins bon et augmente le risque de <strong>syndrome de levée d'obstacle (SLO)</strong> post-drainage. Il nécessite une <strong>surveillance rapprochée</strong>.</p>"},{"i":"18e4bf50664b","n":347,"o":"347-9","u":"Identifier une urgence","t":"Connaître les éléments de gravité en cas de rétention aiguë d’urine","q":"Quelle est la principale situation justifiant une vigilance accrue face à une rétention aiguë d'urine (RAU) avec apparition de fièvre ?","a":"<p>L'apparition de <strong>fièvre</strong> lors d'une RAU évoque une <strong>prostatite aiguë</strong>, faisant craindre un <strong>sepsis</strong>. Cela impose une <strong>hospitalisation</strong> et une <strong>antibiothérapie probabiliste</strong> puis adaptée, après réalisation d'une bandelette urinaire et d'un ECBU.</p>"},{"i":"6772ec75e595","n":347,"o":"347-9","u":"Identifier une urgence","t":"Connaître les éléments de gravité en cas de rétention aiguë d’urine","q":"Comment doit être prise en charge une hématurie associée à une rétention aiguë d'urine ?","a":"<p>Une <strong>hématurie associée</strong> à une RAU nécessite un <strong>sondage</strong> vésical et la réalisation de <strong>lavages par sonde double courant</strong>. Un <strong>bilan étiologique</strong> doit être entrepris secondairement, notamment à la recherche d'une <strong>tumeur</strong> urothéliale.</p>"},{"i":"69b176f54314","n":347,"o":"347-9","u":"Identifier une urgence","t":"Connaître les éléments de gravité en cas de rétention aiguë d’urine","q":"Quelle est la complication à long terme d'une distension vésicale prolongée lors d'une rétention aiguë d'urine ?","a":"<p>Une distension vésicale prolongée peut entraîner une <strong>vessie claquée</strong>, correspondant à un <strong>claquage du détrusor</strong> et une <strong>perte de sa contractilité</strong>. Les séquelles peuvent être des <strong>diverticules vésicaux</strong>, des <strong>récidives de RAU</strong> ou une <strong>rétention chronique</strong>. Cela justifie parfois d'attendre quelques jours ou semaines avant d'ôter une sonde à demeure.</p>"},{"i":"6c997aaa0d8a","n":347,"o":"347-9","u":"Identifier une urgence","t":"Connaître les éléments de gravité en cas de rétention aiguë d’urine","q":"Quelles sont les complications post-drainage aiguës principales à prévenir dans un contexte de rétention aiguë d'urine ?","a":"<p>Les principales complications post-drainage aiguës à prévenir sont :</p><ul><li>Le <strong>syndrome de levée d'obstacle (SLO)</strong> : polyurie majeure avec risque d'<strong>hypokaliémie</strong> et de <strong>déshydratation</strong>.</li><li>L'<strong>hématurie <em>a vacuo</em></strong> : saignement lié à la vidange trop rapide de la vessie, favorisé par des troubles de l'hémostase ou des anticoagulants.</li></ul>"},{"i":"958809d4335f","n":347,"o":"347-9","u":"Identifier une urgence","t":"Connaître les éléments de gravité en cas de rétention aiguë d’urine","q":"Quel est le risque de la rétention aiguë d'urine sur le parenchyme rénal ?","a":"<p>La RAU peut entraîner une <strong>insuffisance rénale aiguë obstructive</strong> par <strong>rétrocession sur le haut appareil</strong>, visible par une <strong>dilatation bilatérale des cavités</strong> à l'échographie et une <strong>augmentation de la créatininémie</strong>. Cette IRA est généralement <strong>régressive</strong> après drainage, bien que la dilatation puisse persister quelques semaines.</p>"}]};